import{_ as n,a0 as p,w as a,s,ao as u,I as o,a1 as i,A as r,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"一種新的安全檢測的方法 | LCTT x X-CMD","titleTemplate":false,"description":"一種新的安全檢測的方法 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一種新的安全檢測的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一種新的安全檢測的方法 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20180412 A new approach to security instrumentation","title":"一種新的安全檢測的方法","tag":"201812","desc":""},"relativePath":"201812/20180412 A new approach to security instrumentation.md","filePath":"[post].md"}'),m={name:"201812/20180412 A new approach to security instrumentation.md"};function d(f,t,T,b,C,h){const l=p("Link");return a(),s("div",null,[t[16]||(t[16]=u('<h1 id="一種新的安全檢測的方法" tabindex="-1">一種新的安全檢測的方法 <a class="header-anchor" href="#一種新的安全檢測的方法" aria-label="Permalink to “一種新的安全檢測的方法”">​</a></h1><blockquote><p>不要只測試已有系統，強安全要求更積極主動的策略。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/security_privacy_lock.png?itok=ZWjrpFzx" alt=""></p><p>我們當中有多少人曾説出過下面這句話：“我希望這能起到作用！”？</p><p>毫無疑問，我們中的大多數人可能都不止一次地説過這句話。這句話不是用來激發信心的，相反它揭示了我們對自身能力和當前正在測試的功能的懷疑。不幸的是，這句話非常好地描述了我們傳統的安全模型。我們的運營基於這樣的假設，並希望我們實施的控制措施 —— 從 web 應用的漏掃到終端上的殺毒軟件 —— 防止惡意的病毒和軟件進入我們的系統，損壞或偷取我們的信息。</p><p>滲透測試通過積極地嘗試侵入網絡、向 web 應用注入惡意代碼或者通過發送釣魚郵件來傳播病毒等等這些步驟來避免我們對假設的依賴。由於我們在不同的安全層面上來發現和滲透漏洞，手動測試無法解決漏洞被主動打開的情況。在安全實驗中，我們故意在受控的情形下創造混亂，模擬事故的情形，來客觀地檢測我們檢測、阻止這類問題的能力。</p><blockquote><p>“安全實驗為分佈式系統的安全性實驗提供了一種方法，以建立對抗惡意攻擊的能力的信心。”</p></blockquote><p>在分佈式系統的安全性和複雜性方面，需要反覆地重申混沌工程界的一句名言，“希望不是一種有效的策略”。我們多久會主動測試一次我們設計或構建的系統，來確定我們是否已失去對它的控制？大多數組織都不會發現他們的安全控制措施失效了，直到安全事件的發生。我們相信“安全事件不是偵察措施”，而且“希望不要出事也不是一個有效的策略”應該是 IT 專業人士執行有效安全實踐的口號。</p><p>行業在傳統上強調預防性的安全措施和縱深防禦，但我們的任務是通過偵探實驗來驅動對安全工具鏈的新知識和見解。因為過於專注於預防機制，我們很少嘗試一次以上地或者年度性地手動測試要求的安全措施，來驗證這些控件是否按設計的那樣執行。</p><p>隨着現代分佈式系統中的無狀態變量的不斷改變，人們很難充分理解他們的系統的行為，因為會隨時變化。解決這個問題的一種途徑是通過強大的系統性的設備進行檢測，對於安全性檢測，你可以將這個問題分成兩個主要方面：<strong>測試</strong>，和我們稱之為<strong>實驗</strong>的部分。測試是對我們已知部分的驗證和評估，簡單來説，就是我們在開始找之前，要先弄清楚我們在找什麼。另一方面，實驗是去尋找獲得我們之前並不清楚的見解和知識。雖然測試對於一個成熟的安全團隊來説是一項重要實踐，但以下示例會有助於進一步地闡述兩者之間的差異，並對實驗的附加價值提供一個更為貼切的描述。</p><h3 id="示例場景-精釀啤酒" tabindex="-1">示例場景：精釀啤酒 <a class="header-anchor" href="#示例場景-精釀啤酒" aria-label="Permalink to “示例場景：精釀啤酒”">​</a></h3><p>思考一個用於接收精釀啤酒訂單的 web 服務或者 web 應用。</p><p>這是這家精釀啤酒運輸公司的一項重要服務，這些訂單來自客户的移動設備、網頁，和通過為這家公司精釀啤酒提供服務的餐廳的 API。這項重要服務運行在 AWS EC2 環境上，並且公司認為它是安全的。這家公司去年成功地通過了 PCI 規則，並且每年都會請第三方進行滲透測試，所以公司認為這個系統是安全的。</p><p>這家公司有時一天兩次部署來進行 DevOps 和持續交付工作，公司為其感到自豪。</p><p>在瞭解了混沌工程和安全實驗方面的東西后，該公司的開發團隊希望能確定，在一個連續不斷的基礎上，他們的安全系統對真實世界事件的有效性和快速恢復性怎麼樣。與此同時，確保他們不會把安全控件不能檢測到的新問題引入到系統中。</p><p>該團隊希望能小規模地通過評估端口安全和防火牆設置來讓他們能夠檢測、阻止和警告他們 EC2 安全組上端口設置的錯誤配置更改。</p><ul><li>該團隊首先對他們正常狀態下的假設進行總結。</li><li>在 EC2 實例裏為端口安全進行一個假設。</li><li>為未認證的端口改變實驗選擇和配置 YAML 文件。</li><li>該配置會從已選擇的目標中隨機指定對象，同時端口的範圍和數量也會被改變。</li><li>團隊還會設置進行實驗的時間並縮小爆破攻擊的範圍，來確保對業務的影響最小。</li><li>對於第一次測試，團隊選擇在他們的測試環境中運行實驗並運行一個單獨的測試。</li><li>在真實的<ruby>遊戲日<rt>Game Day</rt></ruby>風格里，團隊在預先計劃好的兩個小時的窗口期內，選擇<ruby>災難大師<rt>Master of Disaster</rt></ruby>來運行實驗。在那段窗口期內，災難大師會在 EC2 實例安全組中的一個實例上執行這次實驗。</li><li>一旦遊戲日結束，團隊就會開始進行一個徹底的、免於指責的事後練習。它的重點在於針對穩定狀態和原始假設的實驗結果。問題會類似於下面這些：</li></ul><h3 id="事後驗證問題" tabindex="-1">事後驗證問題 <a class="header-anchor" href="#事後驗證問題" aria-label="Permalink to “事後驗證問題”">​</a></h3><ul><li>防火牆是否檢測到未經授權的端口更改？</li><li>如果更改被檢測到，更改是否會被阻止？</li><li>防火牆是否會將有用的日誌信息記錄到日誌聚合工具中？</li><li>SIEM 是否會對未經授權的更改發出警告？</li><li>如果防火牆沒有檢測到未經授權的更改，那麼配置的管理工具是否發現了這次更改？</li><li>配置管理工具是否向日志聚合工具報告了完善的信息？</li><li>SIEM 最後是否進行了關聯報警？</li><li>如果 SIEM 發出了警報，安全運營中心是否能收到這個警報？</li><li>獲得警報的 SOC 分析師是否能對警報採取措施，還是缺少必要的信息？</li><li>如果 SOC 確定警報是真實的，那麼安全事件響應是否能簡單地從數據中進行分類活動？</li></ul><p>我們系統中對失敗的承認和預期已經開始揭示我們對系統工作的假設。我們的使命是利用我們所學到的，並更加廣泛地應用它。以此來真正主動地解決安全問題，來超越當前傳統主流的被動處理問題的安全模型。</p><p>隨着我們繼續在這個新領域內進行探索，我們一定會發布我們的研究成果。如果您有興趣想了解更多有關研究的信息或是想參與進來，請隨時聯繫 Aaron Rinehart 或者 Grayson Brewer。</p><p>特別感謝 Samuel Roden 對本文提供的見解和想法。</p>',22)),o("ul",null,[o("li",null,[i(l,{href:"https://opensource.com/article/18/4/devsecops"},{default:r(()=>[...t[0]||(t[0]=[e("看我們相關的文章：是否需要 DevSecOps 這個詞？",-1)])]),_:1})])]),t[17]||(t[17]=o("hr",null,null,-1)),o("p",null,[t[2]||(t[2]=e("via: ",-1)),i(l,{href:"https://opensource.com/article/18/4/new-approach-security-instrumentation"},{default:r(()=>[...t[1]||(t[1]=[e("https://opensource.com/article/18/4/new-approach-security-instrumentation",-1)])]),_:1})]),o("p",null,[t[7]||(t[7]=e("作者：",-1)),i(l,{href:"https://opensource.com/users/aaronrinehart"},{default:r(()=>[...t[3]||(t[3]=[e("Aaron Rinehart",-1)])]),_:1}),t[8]||(t[8]=e(" 選題：",-1)),i(l,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[4]||(t[4]=[e("lujun9972",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),i(l,{href:"https://github.com/hopefully2333"},{default:r(()=>[...t[5]||(t[5]=[e("hopefully2333",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const w=n(m,[["render",d]]);export{x as __pageData,w as default};
